class Solution {
    public long minEnd(int n,int x){
        long remaining=n-1L,answer=x;
        int bit=0;
        while(remaining>0){
            long mask=1L<<bit;
            if((answer&mask)==0){
                if((remaining&1)==1)answer|=mask;
                remaining>>=1;
            }
            bit++;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minEnd(n:Int,x:Int):Long{
        var remaining=n-1L;
        var answer=x.toLong();
        var bit=0;
        while(remaining>0){
            val mask=1L shl bit;
            if(answer and mask==0L){
                if(remaining and 1L==1L)answer=answer or mask;
                remaining=remaining shr 1
            };
            bit++
        };
        return answer
    }
}

